          "description": "我在当前场景要完成的事项。"
        },
        "immediate": {
          "type": "string",
          "description": "我在本轮行动要完成的事项。"
        },
        "actionFocus": {
          "type": "string",
          "enum": [
            "交流",
            "互动"
