responseSchemaParserJs:
try {
    const parts = responseJson?.candidates?.[0]?.content?.parts;
    if (!parts || !Array.isArray(parts) || parts.length === 0) {
        return { error: 'No content parts found in response' };
    }

    const potentialDataSource = parts[0];
    let rawText = '';

    if (typeof potentialDataSource === 'object' && potentialDataSource !== null && typeof potentialDataSource.text === 'string') {
        rawText = potentialDataSource.text;
    } else if (typeof potentialDataSource === 'string') {
        rawText = potentialDataSource;
    } else {
         return { error: 'Response data part is not a string and not an object containing text.', rawData: potentialDataSource };
    }

    let jsonString = '';
    const firstBraceIndex = rawText.indexOf('{');
    const lastBraceIndex = rawText.lastIndexOf('}');

    if (firstBraceIndex !== -1 && lastBraceIndex !== -1 && lastBraceIndex > firstBraceIndex) {
        jsonString = rawText.substring(firstBraceIndex, lastBraceIndex + 1);
    } else {
        return { error: 'Could not find valid JSON braces {} within the response text.', rawText: rawText };
    }

    let data;
    try {
        data = JSON.parse(jsonString);
    } catch (e) {
        return { error: `Failed to parse extracted JSON: ${e.message}`, rawText: rawText, extractedJson: jsonString };
    }

    if (!data || typeof data !== 'object') {
       return { error: 'Parsed data is not a valid object.', rawText: rawText, extractedJson: jsonString };
    }

    if (!data.rolePlay || !Array.isArray(data.rolePlay.turnActions) || data.rolePlay.turnActions.length === 0) {
         return { error: 'Missing or invalid rolePlay.turnActions array (cannot be empty)' };
    }
    if (!data.data || typeof data.data !== 'object') {
        return { error: 'Missing or invalid top-level "data" object' };
    }
    if (!data.data.createdCharacterInfo) {
        return { error: 'Missing or invalid data.createdCharacterInfo object' };
    }
    if (!data.data.sceneContext) {
        return { error: 'Missing or invalid data.sceneContext object' };
    }
    if (!data.data.nextTurnSelection || !data.data.nextTurnSelection.selectedCharacterName) {
         return { error: 'Missing or invalid data.nextTurnSelection object or selectedCharacterName' };
    }

    const nextCharacter = data.data.nextTurnSelection.selectedCharacterName;
    const charName = data.data.createdCharacterInfo.characterName;
    const actionFocus = data.rolePlay.actionFocus || '未指定';

    const processedTurnActions = [];

    for (const action of data.rolePlay.turnActions) {
        let effectiveType = action.type;

        // 兼容旧的缓存输出
        if (effectiveType === 'critical_action' || effectiveType === 'non_critical_action') {
            effectiveType = 'action';
        }

        let processedContent = (action.content || '').trim();

        // 1. 强力剥离两端的各种引号、括号和方括号 (中英文)
        const stripRegex = /^["“”'‘’()（）\[\]【】\s]+|["“”'‘’()（）\[\]【】\s]+$/g;
        processedContent = processedContent.replace(stripRegex, '');

        // 2. 全局剥离代词，特别是第一人称生成的“我” (仅适用于动作和描述，不适用于言语和思考)
        if (['action', 'description'].includes(effectiveType) && charName) {
            const escapedCharName = charName.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
            const globalPronounRegex = new RegExp(`((我(的)?)|(他(的)?)|(她(的)?)|(它(的)?)|(${escapedCharName}(的)?))`, 'g');
            processedContent = processedContent.replace(globalPronounRegex, '');
            // 移除因为去除主语而暴露在开头的逗号、句号等标点
            processedContent = processedContent.replace(/^[，。！？,.!?\s]+/, '');
            // 移除连续重复的标点
            processedContent = processedContent.replace(/([，。！？,.!?])\1+/g, '$1');
            processedContent = processedContent.trim();
        }

        if (processedContent.length === 0) {
            continue;
        }

        // 3. 根据类型重新包裹指定的符号 (仅限言语)
        if (effectiveType === 'speech') {
            processedContent = `“${processedContent}”`;
        }
        // action, thoughts, description 保持原样

        processedTurnActions.push({ type: effectiveType, content: processedContent });
    }

    if (processedTurnActions.length === 0) {
         return { error: 'All turn actions resulted in empty content after processing.' };
    }

    const charInfo = data.data.createdCharacterInfo;

    // 清洗发型
    if (charInfo.hairstyle) {
        const removeColorPrefix = (str) => {
            if (typeof str !== 'string') return str;
            const idx = str.lastIndexOf('色');
            return idx !== -1 ? str.substring(idx + 1) : str;
        };

        if (Array.isArray(charInfo.hairstyle)) {
            charInfo.hairstyle = charInfo.hairstyle.map(removeColorPrefix);
        } else if (typeof charInfo.hairstyle === 'string') {
            charInfo.hairstyle = removeColorPrefix(charInfo.hairstyle);
        }
    }

    // 剔除 shortTermStatus 中包含“发”的条目
    if (Array.isArray(charInfo.shortTermStatus)) {
        charInfo.shortTermStatus = charInfo.shortTermStatus.filter(item => typeof item !== 'string' || !item.includes('发'));
    } else if (typeof charInfo.shortTermStatus === 'string' && charInfo.shortTermStatus.includes('发')) {
        charInfo.shortTermStatus = null;
    }

    const flattenAndFilter = (value) => {
        const results = [];
        const processItem = (item) => {
            if (typeof item === 'string') {
                const trimmed = item.trim();
                if (trimmed) results.push(trimmed);
            } else if (Array.isArray(item)) {
                item.forEach(subItem => processItem(subItem));
            } else if (typeof item === 'object' && item !== null) {
                Object.values(item).forEach(subItem => processItem(subItem));
            }
        };
        if (value !== undefined && value !== null) processItem(value);

        if (results.length === 0) return ["无"];
        const filteredResults = results.filter(item => item !== "无");
        return filteredResults.length > 0 ? filteredResults : ["无"];
    };

    // 提取模块一中的内部目标至状态栏 (不再混入 actionFocus)
    const rolePlay = data.rolePlay || {};
    let goalItems = [];
    if (rolePlay.daily) goalItems.push(`今日: ${rolePlay.daily}`);
    if (rolePlay.immediate) goalItems.push(`本轮: ${rolePlay.immediate}`);

    if (goalItems.length > 0) {
        goalItems = goalItems.map(item => {
            if (!item.includes('(不可见)')) {
                return `${item} (不可见)`;
            }
            return item;
        });
    } else {
        goalItems = ["无 (不可见)"];
    }

    const processedCharInfo = {
        characterName: charInfo.characterName,
        internalGoalItems: goalItems,
        demeanorItems: flattenAndFilter(charInfo.demeanor),
        outerwearItems: flattenAndFilter(charInfo.clothing?.outerwear),
        underwearItems: flattenAndFilter(charInfo.clothing?.underwear),
        accessories: flattenAndFilter(charInfo.accessories),
        shortTermStatusItems: flattenAndFilter([charInfo.hairstyle, charInfo.shortTermStatus]),
        actionPoseItems: flattenAndFilter(charInfo.actionPose),
        currentPositionItems: flattenAndFilter(charInfo.currentPosition)
    };

    const scene = data.data.sceneContext;
    const processedScene = {
        timeItems: flattenAndFilter(scene.time),
        locationItems: flattenAndFilter(scene.location)
    };

    return {
        nextCharacter: nextCharacter,
        actionFocus: actionFocus, // 作为顶层属性独立输出
        processedTurnActions: processedTurnActions,
        processedCharacterInfo: processedCharInfo,
        processedSceneContext: processedScene
    };

} catch (e) {
    const rawResponseTextForError = responseJson?.candidates?.[0]?.content?.parts?.[0]?.text || "Raw text not available";
    console.error("Parser Error:", e);
    return {
        error: `Parser exception: ${e.message}`,
        rawResponseForDebugging: rawResponseTextForError,
        stack: e.stack
    };
}

